                if (da) decisions.defAdjacent = parseFloat(da.value) || 0;
                if (ns) decisions.narrative = ns.value;
                var defTotal = decisions.defBeachhead + decisions.defAdjacent;
                if (Math.abs(defTotal - 250) > 1) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('def_total_warning'), 'warning');
                    return false;
                }
            } else if (round === 4) {
                var sc = document.getElementById('scalingSelect');
                var fi = document.getElementById('financingSelect');
                if (sc) decisions.scaling = sc.value;
                if (fi) decisions.financing = fi.value;
            }
            return true;
        }

        calculateResults(state) {
            var out = this._computeRound(state);
            return out;
        }

        // Pragmatist acceptance of the whole product: a soft threshold at WPCS 65 (case, Industry context:
        // pragmatist acceptance threshold 65). Returns a factor from about 0.3 to 1.2.
        _accept(wpcs) {
            return 0.3 + 0.9 / (1 + Math.exp(-(wpcs - 65) / 5));
        }

        // Adoption room left in the segment inside the 18-month window.
        _room(ds, seg) {
            var cap = seg.tam * this.REACH;
            return Math.max(0, 1 - ((ds.segCustomers || 0) + (ds.rivalAdopters || 0)) / cap);
        }

        // ARR by cohort: the 47 legacy farms keep their PYG 18M contracts, beachhead and pin customers pay
        // their own segment price. A list-price cut reaches every renewal.
        _arr(ds, seg) {
            var cut = typeof ds.listCut === 'number' ? ds.listCut : 1;
            var adjSeg = this.SEGMENTS[seg.adj];
            var seg0 = Math.max(0, ds.segCustomers || 0), adj = Math.max(0, ds.adjCustomers || 0);
            var legacy = Math.max(0, ds.customers - seg0 - adj);
            return Math.round((legacy * 18000000 + seg0 * seg.acv * 1000000 * ds.priceIndex + adj * adjSeg.acv * 1000000) * cut);
        }

        _share(ds) {
            var a = ds.segCustomers || 0, b = ds.rivalAdopters || 0;
            return (a + b) > 0 ? Math.round((a / (a + b)) * 1000) / 10 : 0;
        }

        _computeRound(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var round = state.currentPeriod;
            if (typeof ds.segCustomers !== 'number') { ds.segCustomers = 0; }
            if (typeof ds.rivalAdopters !== 'number') { ds.rivalAdopters = 0; }
            if (typeof ds.adjCustomers !== 'number') { ds.adjCustomers = 0; }
            if (typeof ds.priceIndex !== 'number') { ds.priceIndex = 1; }
            if (typeof ds.acqSpend !== 'number') { ds.acqSpend = 0; }
            if (typeof ds.acqArr !== 'number') { ds.acqArr = 0; }
            if (!ds.flags || typeof ds.flags !== 'object') { ds.flags = {}; }
            if (!Array.isArray(ds.log)) { ds.log = []; }
            ds.log = ds.log.filter(function (x) { return x && x.round < round; });
            var flagNames = ['bigSeg', 'evenSplit', 'directHeavy', 'priceCut', 'goBroad', 'storyMismatch', 'freemiumTrap'];
            var flagRound = { bigSeg: 1, evenSplit: 1, directHeavy: 2, freemiumTrap: 2, priceCut: 3, goBroad: 3, storyMismatch: 3 };
            for (var fi = 0; fi < flagNames.length; fi++) { if (flagRound[flagNames[fi]] >= round) { delete ds.flags[flagNames[fi]]; } }

            var seg = this.SEGMENTS[ds.beachheadIndex >= 0 ? ds.beachheadIndex : 0];
            var events = this._rollEvents(round);
            ds.roundEvents = events;
            var eventCashBonus = 0, eventWpcsModifier = 0, eventDigitalBoost = 0, eventAdoptionBoost = 0;
            var eventChurnHit = 0, eventPricePressure = 0, eventChannelDisruption = 0, acquisitionOffered = false;
            for (var i = 0; i < events.length; i++) {
                var ev = events[i];
                if (ev === 'mercosur_grant') eventCashBonus = 2175000000;
                if (ev === 'ref_churn') eventWpcsModifier = -12;
                if (ev === 'internet_expand') eventDigitalBoost = 0.30;
                if (ev === 'gov_mandate') eventAdoptionBoost = 0.40;
                if (ev === 'agriglobal_offer') acquisitionOffered = true;
                if (ev === 'drought') eventChurnHit = 0.15;
                if (ev === 'competitor_freemium') eventPricePressure = 0.20;
                if (ev === 'distributor_defects') eventChannelDisruption = 0.30;
            }
            ds.cash += eventCashBonus;

            var newCustomers = 0, revenue = 0, costs = 0, roundInvestment = 0, acqSpend = 0;
            var cciValue = 0, caeValue = 0, bowlingChange = 0, churned = 0, newSeg = 0;
            var acv = seg.acv * 1000000 * ds.priceIndex * (typeof ds.listCut === 'number' ? ds.listCut : 1);

            if (round === 1) {
                ds.beachheadIndex = d.beachhead;
                seg = this.SEGMENTS[d.beachhead] || this.SEGMENTS[0];
                acv = seg.acv * 1000000 * ds.priceIndex;
                var alloc = [d.wpEcosystem, d.wpLocalization, d.wpReference, d.wpContent];
                var wpInvestTotal = alloc[0] + alloc[1] + alloc[2] + alloc[3];
                roundInvestment = wpInvestTotal * 1000000;
                // Each gap closes along an S-curve (half closed at 50M): a gap gets closed or it does not, and a
                // budget spread thin over every gap closes none of the critical ones (Moore 2014 ch.5, Levitt 1980).
                var closure = 0;
                for (var k = 0; k < 4; k++) {
                    var x = Math.max(0, alloc[k]);
                    closure += seg.wpW[k] * (x * x) / (x * x + 2500);
                }
                ds.wpClosure = Math.round(closure * 1000) / 1000;
                var rawWpcs = (100 - seg.wpGap) + seg.wpGap * closure;
                rawWpcs = Math.min(95, Math.max(10, rawWpcs)) + eventWpcsModifier;
                ds.wpcs = Math.round(Math.max(0, rawWpcs));
                ds.rivalAdopters = seg.tam * this.BASE_PEN;
                var initialAdoption = Math.round(seg.tam * 0.005 * (seg.pain / 10) * this._accept(ds.wpcs) * this._room(ds, seg));
                newSeg = Math.max(1, initialAdoption);
                ds.segCustomers += newSeg;
                newCustomers = newSeg;
                ds.customers += newCustomers;
                ds.arr = this._arr(ds, seg);
                acqSpend = roundInvestment * 0.5;
                if (Math.max.apply(null, alloc) <= 0.3 * 180) ds.flags.evenSplit = true;
                if (d.beachhead === 1) ds.flags.bigSeg = true;

            } else if (round === 2) {
                var gtmTotal = (d.gtmDirect + d.gtmChannel + d.gtmDigital + d.gtmExtension) * 1000000;
                roundInvestment = gtmTotal;
                acqSpend = gtmTotal;
                // Each channel has a capacity (8 sellers, a handful of distributors, rural connectivity, co-op
                // bandwidth): returns are linear at first and flatten as the channel fills.
                var reachOf = function (b, cac, cap) { return b > 0 ? (cap / cac) * (1 - Math.exp(-b / cap)) : 0; };
                var directEff = reachOf(d.gtmDirect, seg.cacDirect, 100);
                var channelEff = reachOf(d.gtmChannel, seg.cacChannel, 150) * 1.2;
                var digitalEff = reachOf(d.gtmDigital, seg.cacDigital, 60) * (0.7 + eventDigitalBoost);
                var extensionEff = reachOf(d.gtmExtension, seg.cacExtension, 50) * 0.4;
                var pricingMult = 1.0, acvMult = 1.0;
                // The bundle finances the sensors inside the subscription: a modest ARR uplift, hardware paid up front.
                if (d.pricing === 'bundle') { pricingMult = 0.85; acvMult = 1.15; }
                if (d.pricing === 'freemium') { pricingMult = ds.wpcs > 60 ? 1.3 : 0.5; acvMult = 0.6; if (ds.wpcs <= 60) ds.flags.freemiumTrap = true; }
                ds.priceIndex = acvMult;
                acv = seg.acv * 1000000 * ds.priceIndex;
                var refMult = 1.0;
                if (d.referenceInit === 'pilot') refMult = 1.15;
                if (d.referenceInit === 'comarketing') refMult = 1.25;
                if (d.referenceInit === 'casestudy') refMult = 1.1;
                refMult *= seg.refMult;
                ds.wpcs = Math.max(0, ds.wpcs + eventWpcsModifier);
                // 1.6 calibrates the volume to the case: Option A reaches about PYG 2.4B ARR in 18 months.
                var rawNew = 1.6 * (directEff + channelEff + digitalEff + extensionEff) * pricingMult * refMult * (1 + eventAdoptionBoost)
                    * this._accept(ds.wpcs) * (seg.pain / 8) * this._room(ds, seg);
                newSeg = Math.max(0, Math.round(rawNew));
                newCustomers = newSeg;
                var churnRate = seg.churnSens * 0.05 + eventChurnHit;
                churned = Math.round(ds.customers * churnRate);
                ds.segCustomers = Math.max(0, ds.segCustomers + newSeg - Math.round(churned * ds.segCustomers / Math.max(1, ds.customers)));
                ds.customers = ds.customers + newCustomers - churned;
                ds.arr = this._arr(ds, seg);
                if (d.pricing === 'bundle') { ds.cash -= newSeg * 6000000; }
                if (d.gtmDirect >= 0.5 * 220) ds.flags.directHeavy = true;

            } else if (round === 3) {
                roundInvestment = 250000000;
                var defenseRatio = d.defBeachhead / 250;
                var adjacentRatio = d.defAdjacent / 250;
                acqSpend = d.defAdjacent * 1000000;
                var compEffect = 0;
                if (d.compResponse === 'price') compEffect = -5;
                if (d.compResponse === 'switching') compEffect = 15;
                if (d.compResponse === 'bowling') { compEffect = 5; }
                if (d.compResponse === 'partnership') compEffect = 10;
                var shareBefore = this._share(ds);
                // A price cut matches part of the gap to AgriGlobal and holds customers this round, but every
                // contract renews at the lower price from now on (case Option B, USD 2,480 to 1,800).
                ds.listCut = 1;
                if (d.compResponse === 'price') { ds.listCut = 0.73; ds.flags.priceCut = true; }
                acv = seg.acv * 1000000 * ds.priceIndex * ds.listCut;
                var competitivePos = 50 + (ds.wpcs - 70) * 0.5 + compEffect + defenseRatio * 10 - seg.agExp * 20;
                ds.competitivePosition = Math.round(Math.min(100, Math.max(0, competitivePos)));
                // AgriGlobal wins adopters in the segment; a defended beachhead with switching costs slows it.
                var shield = 0.6 * defenseRatio + (d.compResponse === 'switching' ? 0.3 : 0);
                ds.shield = Math.min(0.9, shield);
                ds.rivalAdopters += seg.tam * 0.02 * seg.agExp * Math.max(0.1, 1 - shield);
                // Word of mouth inside the beachhead: references sell to neighbours (case, reference customer quote).
                // References carry only from a beachhead you lead: nothing below 15% share, full from 40%.
                var refLev = Math.max(0, Math.min(1, (shareBefore - 15) / 25));
                var wom = ds.segCustomers * (0.15 + 0.35 * refLev) * (0.5 + defenseRatio) * this._accept(ds.wpcs)
                    * (1 + eventAdoptionBoost) * this._room(ds, seg);
                // Pragmatists buy from stable vendors (Moore 2014 ch.2): while acquisition talks run, farms wait.
                if (d.compResponse === 'partnership') wom = wom * 0.75;
                newSeg = Math.max(0, Math.round(wom));
                // First bowling-alley pin: it needs references from a beachhead already led (Moore 2014 ch.4).
                var adjSeg = this.SEGMENTS[seg.adj];
                // The pin has its own whole-product gap; about half of the beachhead partners carry over.
                var adjWpcs = (100 - adjSeg.wpGap) + adjSeg.wpGap * (ds.wpClosure || 0.5) * 0.5;
                var adjNew = Math.round(adjSeg.tam * 0.01 * adjacentRatio * this._accept(adjWpcs) * (0.3 + 0.7 * refLev));
                ds.adjCustomers += adjNew;
                // Poaching by AgriGlobal plus support diverted to the new segment.
                var poach = seg.agExp * 0.10 * (d.compResponse === 'switching' ? 0.3 : (d.compResponse === 'price' ? 0.4 : 1));
                var diverted = Math.max(0, adjacentRatio - 0.4) * 0.3;
                var churnRate3 = seg.churnSens * 0.04 + eventChurnHit + poach + diverted;
                var segLoss = Math.round(ds.segCustomers * churnRate3);
                var legacyLoss = Math.round((ds.customers - ds.segCustomers - (ds.adjCustomers - adjNew)) * (seg.churnSens * 0.04 + eventChurnHit));
                churned = segLoss + Math.max(0, legacyLoss);
                ds.segCustomers = Math.max(0, ds.segCustomers + newSeg - segLoss);
                newCustomers = newSeg + adjNew;
                ds.customers = Math.max(0, ds.customers + newCustomers - churned);
                ds.arr = this._arr(ds, seg);
                if (d.defAdjacent > d.defBeachhead && shareBefore < 30) ds.flags.goBroad = true;
                // Investor narrative: credible only when the numbers carry it.
                var credible = false;
                if (d.narrative === 'growth') credible = ds.arr >= 1500000000;
                if (d.narrative === 'defensibility') credible = ds.competitivePosition >= 60;
                if (d.narrative === 'exit') credible = acquisitionOffered;
                ds.investorScore = Math.max(0, Math.min(100, (ds.investorScore || 50) + (credible ? 15 : -15)));
                if (!credible) ds.flags.storyMismatch = true;

            } else if (round === 4) {
                var scalingCost = 180000000;
                roundInvestment = scalingCost;
                acqSpend = scalingCost;
                var scaleMult = 1.0, churnReduction = 0;
                var r2 = this._decisionsOf(state, 2);
                var chanShare = r2 ? (r2.gtmChannel + r2.gtmExtension) / 220 : 0.5;
                if (d.scaling === 'channel_mgmt') { scaleMult = 0.9 + 0.5 * chanShare; churnReduction = 0.02; }
                if (d.scaling === 'direct_expand') { scaleMult = 1.25; roundInvestment += 120000000; acqSpend += 120000000; }
                if (d.scaling === 'platform_api') { scaleMult = 1.0; churnReduction = 0.03; }
                var financeCash = 0;
                if (d.financing === 'bridge') { financeCash = 3000000000; }
                if (d.financing === 'rba') { financeCash = 1500000000; }
                if (d.financing === 'strategic') { financeCash = 2000000000; scaleMult *= 1.1; }
                // Investors fund the story the numbers carried in round 3.
                financeCash = Math.round(financeCash * (0.6 + 0.8 * (ds.investorScore || 50) / 100));
                ds.cash += financeCash;
                if (d.financing === 'rba') { ds.cash -= Math.round(ds.arr * 0.08 / 4); }
                var share4 = this._share(ds);
                var refLev4 = Math.max(0, Math.min(1, (share4 - 15) / 25));
                var pricePressureEffect = 1 - eventPricePressure;
                var channelEffect = 1 - eventChannelDisruption * chanShare;
                // AgriGlobal keeps selling in round 4; the round 3 defence (and its switching costs) still holds it.
                var shield4 = typeof ds.shield === 'number' ? ds.shield : 0.3;
                ds.rivalAdopters += seg.tam * 0.02 * seg.agExp * Math.max(0.1, 1 - shield4);
                // After a list-price cut the reference farms have just been told the product is worth less
                // (case Option B): word of mouth carries less.
                var cutDrag = (typeof ds.listCut === 'number' && ds.listCut < 1) ? 0.75 : 1;
                var growth = cutDrag * ds.segCustomers * (0.15 + 0.25 * refLev4) * scaleMult * pricePressureEffect * channelEffect
                    * this._accept(ds.wpcs) * this._room(ds, seg);
                newSeg = Math.max(0, Math.round(growth));
                var adjSeg4 = this.SEGMENTS[seg.adj];
                var adjGrow = ds.adjCustomers > 0 ? Math.round(ds.adjCustomers * (0.2 + 0.6 * refLev4) * scaleMult) : 0;
                if (d.scaling === 'platform_api' && share4 >= 25) adjGrow += Math.round(adjSeg4.tam * 0.003);
                ds.adjCustomers += adjGrow;
                var churnRate4 = Math.max(0, seg.churnSens * 0.04 - churnReduction);
                churned = Math.round(ds.customers * churnRate4);
                ds.segCustomers = Math.max(0, ds.segCustomers + newSeg - Math.round(churned * ds.segCustomers / Math.max(1, ds.customers)));
                newCustomers = newSeg + adjGrow;
                ds.customers = Math.max(0, ds.customers + newCustomers - churned);
                ds.arr = this._arr(ds, seg);
            }

            // A bowling-alley pin counts once the adjacent segment holds a reference cluster of 10 customers.
            var pins = ds.adjCustomers >= 10 ? 1 : 0;
            if (pins > (ds.bowlingAlleySegments || 0)) bowlingChange = pins - (ds.bowlingAlleySegments || 0);
            ds.bowlingAlleySegments = Math.max(ds.bowlingAlleySegments || 0, pins);

            revenue = ds.arr / 4;
            costs = ds.monthlyBurn * 3 + roundInvestment;
            ds.cash += revenue - costs;
            ds.beachheadShare = this._share(ds);
            var newArr = Math.max(0, newCustomers) * acv;
            // Fully loaded acquisition cost: the 8 commercial staff (8 of 22 on the quarterly burn) as well.
            acqSpend += Math.round(ds.monthlyBurn * 3 * 8 / 22);
            caeValue = acqSpend > 0 ? Math.round(((newArr * 3) / acqSpend) * 10) / 10 : 0;
            ds.cae = caeValue;
            ds.acqSpend += acqSpend;
            ds.acqArr += newArr;
            var caeCum = ds.acqSpend > 0 ? (ds.acqArr * 3) / ds.acqSpend : 0;
            ds.caeCum = Math.round(caeCum * 10) / 10;

            var runway = ds.monthlyBurn > 0 ? Math.round(ds.cash / ds.monthlyBurn) : 0;
            var chasmShareScore = Math.min(100, (ds.beachheadShare / 35) * 100);
            var chasmWpcsScore = Math.min(100, (ds.wpcs / 75) * 100);
            cciValue = Math.round(chasmShareScore * 0.4 + chasmWpcsScore * 0.35 + ds.competitivePosition * 0.25);
            ds.cci = cciValue;
            // Concepts/321 §7: CCI of 60 or more = crossed; the debrief uses the same rule.
            ds.chasmCrossed = cciValue >= 60 && ds.cash > 0;
            ds.arrHistory.push(ds.arr);
            ds.cciHistory.push(cciValue);
            ds.log.push({ round: round, share: ds.beachheadShare, wpcs: ds.wpcs, cci: cciValue, arr: ds.arr, cash: ds.cash });

            var self = this;
            setTimeout(((__eqilNext) => function() {
                self._updateBriefing({ currentPeriod: __eqilNext });
            })(state.currentPeriod + 1), 500);

            var overallScore = this._composite(ds, runway);
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: overallScore });

            return {
                period: state.currentPeriod,
                round: round,
                newCustomers: newCustomers,
                totalCustomers: ds.customers,
                arr: ds.arr,
                revenue: Math.round(revenue),
                costs: Math.round(costs),
                cash: ds.cash,
                wpcs: ds.wpcs,
                cci: cciValue,
                cae: caeValue,
                caeCum: ds.caeCum,
                beachheadShare: ds.beachheadShare,
                competitivePosition: ds.competitivePosition,
                runway: runway,
                bowlingAlley: ds.bowlingAlleySegments,
                events: events,
                acquisitionOffered: acquisitionOffered,
                flags: JSON.parse(JSON.stringify(ds.flags)),
                overallScore: overallScore,
                score: overallScore
            };
        }

        _decisionsOf(state, round) {
            var h = (state && state.history) || (window.mySimulation && window.mySimulation.state && window.mySimulation.state.history) || [];
            for (var i = 0; i < h.length; i++) { if (h[i] && h[i].period === round && h[i].decisions) return h[i].decisions; }
            return null;
        }

        // One composite for the platform grade and the debrief (Concepts/321 §7 weights). CAE is the whole-run
        // LTV:CAC, not the last round alone.
        _composite(ds, runway) {
            var arrIdx = ds.arr / 846000000;
            var s = (ds.cci || 0) * 0.35
                + Math.min(100, (arrIdx / 3.2) * 100) * 0.25
                + Math.min(100, ((ds.caeCum || 0) / 3.0) * 100) * 0.20
                + (runway >= 6 ? 100 : Math.max(0, runway / 6) * 100) * 0.12
                + Math.min(100, ((ds.bowlingAlleySegments || 0) / 3) * 100) * 0.08;
            return Math.max(0, Math.min(100, Math.round(s)));
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('cashDisplay', 'domainState.cash', (v) => '₲' + Math.round(v / 1000000).toLocaleString() + 'M');
            uiManager.bind('arrDisplay', 'domainState.arr', (v) => '₲' + Math.round(v / 1000000).toLocaleString() + 'M');
            uiManager.bind('customersDisplay', 'domainState.customers');
            uiManager.bind('wpcsDisplay', 'domainState.wpcs', (v) => v + '/100');
            uiManager.bind('cciDisplay', 'domainState.cci', (v) => v + '/100');
            uiManager.bind('runwayDisplay', 'domainState.cash', (v) => Math.max(0, Math.round(v / 210000000)) + '');
            this._bindTotals();
        }

        // Live allocation totals next to each budget (display only; validation is unchanged).
        _bindTotals() {
            var groups = [
                { out: 'wpTotalDisplay', target: 180, ids: ['wpEcosystem', 'wpLocalization', 'wpReference', 'wpContent'] },
                { out: 'gtmTotalDisplay', target: 220, ids: ['gtmDirect', 'gtmChannel', 'gtmDigital', 'gtmExtension'] },
                { out: 'defTotalDisplay', target: 250, ids: ['defBeachhead', 'defAdjacent'] }
            ];
            var paint = function (g) {
                var el = document.getElementById(g.out);
                if (!el) return;
                var sum = 0;
                for (var i = 0; i < g.ids.length; i++) { var x = document.getElementById(g.ids[i]); sum += x ? (parseFloat(x.value) || 0) : 0; }
                el.textContent = Math.round(sum) + ' / ' + g.target;
                var box = el.parentElement;
                if (box && box.classList) { if (Math.abs(sum - g.target) > 1) box.classList.add('chasm-sim-alloc-bad'); else box.classList.remove('chasm-sim-alloc-bad'); }
            };
            groups.forEach(function (g) {
                g.ids.forEach(function (id) {
                    var x = document.getElementById(id);
                    if (x && !x.__chasmTotal) { x.__chasmTotal = true; x.addEventListener('input', function () { paint(g); }); x.addEventListener('change', function () { paint(g); }); }
                });
                paint(g);
            });
        }

        getChartConfig() {
            return {
                arrChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [{
                            label: this._t('chart_arr_label'),
                            data: [],
                            borderColor: '#2e7d32',
                            backgroundColor: 'rgba(46,125,50,0.1)',
                            borderWidth: 3,
                            fill: true,
                            tension: 0.3
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: { title: { display: true, text: this._t('chart_arr_title') } },
                        scales: { y: { beginAtZero: true } }
                    }
                },
                cciChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [{
                            label: this._t('chart_cci_label'),
                            data: [],
                            backgroundColor: 'rgba(21,101,192,0.6)',
                            borderColor: '#1565c0',
                            borderWidth: 2
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: { title: { display: true, text: this._t('chart_cci_title') } },
                        scales: { y: { beginAtZero: true, max: 100 } }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.arrHistory.map(function(_, i) { return 'R' + (i + 1); });
            return {
                arrChart: {
                    labels: labels,
                    datasets: [{ data: state.domainState.arrHistory.map(function(v) { return Math.round(v / 1000000); }) }]
                },
                cciChart: {
                    labels: labels,
                    datasets: [{ data: state.domainState.cciHistory }]
                }
            };
        }

        _f(key, vals) {
            var s = this._t(key);
            for (var k in vals) { if (Object.prototype.hasOwnProperty.call(vals, k)) s = s.split('{' + k + '}').join(String(vals[k])); }
            return s;
        }

        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            var last = history[history.length - 1];
            var r = last.results || {};
            var flags = r.flags || {};
            var ds = (window.mySimulation && window.mySimulation.state && window.mySimulation.state.domainState) || {};
            var finalArr = r.arr || 0;
            var arrGrowthIndex = finalArr / 846000000;
            var cci = r.cci || 0;
            var totalScore = (typeof r.overallScore === 'number') ? r.overallScore
