        _rollEvents(round) {
            var triggered = [];
            for (var i = 0; i < this.EVENTS.length; i++) {
                var ev = this.EVENTS[i];
                if (ev.rounds.indexOf(round) >= 0) {
                    if (Math.random() < ev.prob) {
                        triggered.push(ev.id);
                    }
                }
            }
            return triggered;
        }

        _updateBriefing(state) {
            var round = Math.min((state.currentPeriod || 1), 4);
            var briefTitle = document.getElementById('briefingTitle');
            var briefText = document.getElementById('briefingText');
            var eventPanel = document.getElementById('eventPanel');
            var eventText = document.getElementById('eventText');

            if (briefTitle) briefTitle.textContent = window.mySimulation ? window.mySimulation.t('round_' + round + '_briefing_title') : '';
            if (briefText) briefText.textContent = window.mySimulation ? window.mySimulation.t('round_' + round + '_briefing') : '';

            var r1 = document.getElementById('round1Panel');
            var r2 = document.getElementById('round2Panel');
            var r3 = document.getElementById('round3Panel');
            var r4 = document.getElementById('round4Panel');
            if (r1) r1.style.display = round === 1 ? 'block' : 'none';
            if (r2) r2.style.display = round === 2 ? 'block' : 'none';
            if (r3) r3.style.display = round === 3 ? 'block' : 'none';
            if (r4) r4.style.display = round === 4 ? 'block' : 'none';

            var ds = (window.mySimulation && window.mySimulation.state) ? window.mySimulation.state.domainState : null;
            if (ds && ds.roundEvents && ds.roundEvents.length > 0 && eventPanel && eventText) {
                var msgs = [];
                for (var i = 0; i < ds.roundEvents.length; i++) {
                    var key = 'event_' + ds.roundEvents[i];
                    msgs.push(window.mySimulation.t(key));
                }
                eventText.innerHTML = msgs.join('<br><br>');
                eventPanel.style.display = 'block';
            } else if (eventPanel) {
                eventPanel.style.display = 'none';
            }
        }
    }

    document.addEventListener('DOMContentLoaded', function() {
        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(new ChasmAdapter(), {
            simulationType: 'cruzando_el_abismo',
            maxPeriods: 4,
            autoSaveInterval: 30000
        });
    });

})();
